# SPDX-License-Identifier: GPL-3.0-only
# Native TV interface over the validated v5.4 local playback engine.
# Appended by the release builder; no HTML or external Python file is required.

_HG_TV_BASE = Spider
_HG_TV_VERSION = '1.0.0-tv-native-20261017'
_HG_TV_TABS = (
    ('recommend', '推荐榜', 'all', 'ranklist_hot_sc'),
    ('drama', '真人短剧', 'drama', 'ranklist_hot_play_sc'),
    ('manju', '漫剧', 'manju', 'ranklist_hot_play_sc'),
    ('ai', 'AI短剧', 'ai', 'ranklist_hot_play_sc'),
    ('new', '新剧榜', 'all', 'ranklist_new_rank_sc'),
)
_HG_TV_BOARDS = (
    ('ranklist_hot_play_sc', '热播'), ('ranklist_hot_sc', '推荐'),
    ('ranklist_new_rank_sc', '新剧'), ('ranklist_hot_search_sc', '热搜'),
)


class Spider(_HG_TV_BASE):
    def init(self, extend=''):
        super().init(extend)
        self._tv_lock = threading.RLock()
        self._tv_service = None
        self._tv_pages = {}
        self._tv_search_cache = {}

    def getName(self):
        return '红果短剧·TV原生'

    def _tv_directory(self):
        with self._tv_lock:
            if self._tv_service is None:
                engine, _ = self._ensure()
                module = _hg117_module()
                device = engine.protocol.app_device()
                # Fresh local anonymous context; no captured phone/account data.
                opts = {'directory': {'device_id': device['device_id'], 'install_id': device['iid']}}
                self._tv_service = module.DirectoryService(module.SignedReader(engine, opts))
            return self._tv_service

    @staticmethod
    def _tv_card(item):
        sid = str(item.get('id') or item.get('series_id') or '')
        if not re.fullmatch(r'[0-9]{1,22}', sid):
            return None
        name = str(item.get('name') or item.get('series_title') or '').strip()
        if not name:
            return None
        return {'vod_id': sid, 'vod_name': name[:180],
                'vod_pic': str(item.get('pic') or ''),
                'vod_remarks': str(item.get('remark') or item.get('subtitle') or '')[:100],
                'vod_content': str(item.get('story') or '')[:3000]}

    def homeContent(self, filter):
        classes = [{'type_id': key, 'type_name': name} for key, name, _, _ in _HG_TV_TABS]
        result = {'class': classes}
        if filter:
            result['filters'] = {
                key: [{'key': 'board', 'name': '排序', 'value': [
                    {'n': label, 'v': board} for board, label in _HG_TV_BOARDS]}]
                for key in ('drama', 'manju', 'ai')
            }
        return result

    def homeVideoContent(self):
        return {'list': self.categoryContent('recommend', '1', False, {}).get('list', [])}

    def categoryContent(self, tid, pg, filter, extend):
        tab = next((row for row in _HG_TV_TABS if row[0] == str(tid)), None)
        if tab is None:
            raise ValueError('未知红果分类，请刷新配置')
        if not re.fullmatch(r'[0-9]{1,3}', str(pg)) or not 1 <= int(pg) <= 100:
            raise ValueError('分页编号无效')
        page = int(pg)
        extend = extend if isinstance(extend, dict) else {}
        board = str(extend.get('board') or tab[3])
        if board not in dict(_HG_TV_BOARDS):
            raise ValueError('榜单筛选无效，请重新选择')
        # These fixed tabs keep their own meaning when the App retains filters.
        if tid in ('recommend', 'new'):
            board = tab[3]
        service = self._tv_directory()
        key = (tab[0], board)
        with self._tv_lock:
            stamp = __import__('time').monotonic()
            for old_key, old in list(self._tv_pages.items()):
                if stamp - old['at'] > 300:
                    self._tv_pages.pop(old_key, None)
            session = self._tv_pages.setdefault(key, {'at': stamp, 'pages': {}})
            pages = session['pages']
            # Normal TV navigation increments by one. A modest replay recovers
            # page 2-4 after process restoration without unbounded requests.
            if page not in pages:
                start = max(pages, default=0) + 1
                if page - start > 3:
                    raise ValueError('分页会话已过期，请从第1页重新进入')
                for number in range(start, page + 1):
                    previous = pages.get(number - 1)
                    if previous and not previous.get('hasMore'):
                        return {'list': [], 'page': page, 'pagecount': number - 1,
                                'limit': 15, 'total': sum(len(x['items']) for x in pages.values())}
                    args = {'type': tab[2], 'board': board}
                    if previous:
                        args['cursor'] = previous['cursor']
                    pages[number] = service.call('rank', args)
                    if len(pages) > 100:
                        raise ValueError('本轮分页已满，请从第1页重新进入')
            result = pages[page]
            cards = [card for card in (self._tv_card(x) for x in result.get('items', [])) if card]
            return {'list': cards, 'page': page,
                    'pagecount': page + 1 if result.get('hasMore') else page,
                    'limit': 15, 'total': (page - 1) * 15 + len(cards) + int(bool(result.get('hasMore')))}

    def _tv_web_search(self, keyword):
        engine, _ = self._ensure()
        from _hgl14_webdata import json_documents
        url = engine.SITE + '/search/' + __import__('urllib.parse', fromlist=['quote']).quote(keyword, safe='')
        raw, _, _ = engine.remote(url, headers={'User-Agent': engine.UA_WEB, 'Referer': engine.SITE + '/'},
                                   limit=5 * 1024 ** 2, allowed_origin=engine.SITE)
        page = None
        for document in json_documents(raw):
            loaders = document.get('loaderData') if isinstance(document, dict) else None
            for value in (loaders or {}).values():
                if isinstance(value, dict) and isinstance(value.get('searchList'), list):
                    page = value
                    break
            if page is not None:
                break
        if page is None or page.get('isSuccess') is False:
            raise ValueError('红果官网搜索未返回有效数据，请稍后重试')
        cards, seen = [], set()
        for item in page['searchList']:
            data = item.get('video_data') if isinstance(item, dict) else None
            if not isinstance(data, dict):
                continue
            count = engine.integer(data.get('episode_cnt'))
            card = self._tv_card({'id': data.get('series_id'), 'name': data.get('series_title'),
                                  'pic': engine.cover_url(data.get('series_cover')),
                                  'remark': '共 %d 集' % count if count else '',
                                  'story': data.get('series_intro')})
            if card and card['vod_id'] not in seen:
                cards.append(card)
                seen.add(card['vod_id'])
        return cards

    def searchContent(self, key, quick, pg='1'):
        keyword = str(key or '').strip()
        if not keyword or len(keyword) > 120:
            raise ValueError('请输入1至120字的搜索词')
        if not re.fullmatch(r'[0-9]{1,3}', str(pg)) or int(pg) < 1:
            raise ValueError('搜索页码无效')
        if int(pg) != 1:
            return {'list': [], 'page': int(pg), 'pagecount': 1, 'limit': 10, 'total': 0}
        if re.fullmatch(r'[0-9]{15,22}', keyword):
            info = self._ensure()[0].series(keyword)
            card = self._tv_card(info)
            cards = [card] if card else []
        else:
            with self._tv_lock:
                stamp = __import__('time').monotonic()
                cached = self._tv_search_cache.get(keyword)
                if cached and stamp - cached[0] < 300:
                    cards = cached[1]
                else:
                    cards = self._tv_web_search(keyword)
                    if len(self._tv_search_cache) >= 24:
                        self._tv_search_cache.pop(next(iter(self._tv_search_cache)))
                    self._tv_search_cache[keyword] = (stamp, cards)
        return {'list': cards, 'page': 1, 'pagecount': 1, 'limit': max(10, len(cards)), 'total': len(cards)}

    def detailContent(self, ids):
        if not ids:
            return {'list': []}
        engine, _ = self._ensure()
        info = engine.series(str(ids[0]))
        modes = [('高清优先', 'highest'), ('兼容模式', 'compatible')]
        if str(self.options.get('quality', 'highest')) == 'compatible':
            modes.reverse()
        groups = []
        for _, mode in modes:
            groups.append('#'.join(str(ep['name']).replace('$', '').replace('#', '') + '$' +
                                   info['id'] + '|' + ep['id'] + '|' + mode for ep in info['episodes']))
        return {'list': [{'vod_id': info['id'], 'vod_name': info['name'], 'vod_pic': info.get('pic', ''),
                          'vod_content': info.get('story', ''), 'vod_remarks': '全 %d 集' % len(info['episodes']),
                          'vod_play_from': '$$$'.join(name for name, _ in modes),
                          'vod_play_url': '$$$'.join(groups)}]}

    def playerContent(self, flag, id, vipFlags):
        parts = str(id or '').split('|')
        if len(parts) not in (2, 3):
            raise ValueError('选集编号无效，请从详情页重新选集')
        engine, descriptor = self._ensure()
        sid, vid = engine.identity(parts[0]), engine.video_identity(parts[1])
        mode = parts[2] if len(parts) == 3 else str(self.options.get('quality', 'highest'))
        if mode not in ('highest', 'compatible'):
            raise ValueError('画质策略无效')
        with engine.LOCK:
            engine.SERIES_BY_VID[vid] = sid
            while len(engine.SERIES_BY_VID) > 10000:
                engine.SERIES_BY_VID.pop(next(iter(engine.SERIES_BY_VID)))
        path = engine.ticket('/play/' + sid + '/' + vid + '.mp4', {'mode': mode})
        return {'parse': 0, 'jx': 0, 'playUrl': '', 'url': descriptor['base'] + path,
                'header': {}, 'type': 'video/mp4', 'format': 'video/mp4'}

    def action(self, action):
        return {'local': True, 'version': _HG_TV_VERSION, 'repairVersion': '5.4.0-pure-sign-20261017',
                'nativeTV': True, 'htmlRequired': False, 'cacheMB': self.options.get('cache_mb', 512)}
